//! 🪆️ Inline original owners close their child and terminal metadata in separate funded turns.
use semio_framework_value::{ErasedSnapshotRetirement,OriginalRetirementOutcome,OriginalRetirementPoll,OriginalRetirementControl,RetirementSelection,RetainedAllocationEffect,ValueError,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,RetainedCloneStep,RetainedCloneProgress};
/// 🪆️ Quotes the selected original child or its distinct terminal inline slot.
pub fn retirement_owner_demands<O:ErasedSnapshotRetirement>(slot:&Option<O>,body:usize)->Result<RetirementDemand,ValueError>{let Some(owner)=slot.as_ref()else{return Ok(Default::default())};if owner.terminal_is_empty(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<O>>(),depth:1,..Default::default()})}let mut demand=owner.next_demand(body)?;demand.depth=demand.depth.checked_add(1).ok_or_else(||ValueError::literal(semio_framework_value::ValueRefusalKind::DepthLimit,"inline retirement depth overflow"))?;Ok(demand)}
/// ⛽️ Quotes the selected child work or the separate terminal slot action.
pub fn retirement_owner_work_demand<O:ErasedSnapshotRetirement>(slot:&Option<O>,body:usize)->Result<u64,ValueError>{match slot.as_ref(){None=>Ok(0),Some(owner)if owner.terminal_is_empty()=>Ok(1),Some(owner)=>owner.next_computational_work(body)}}
/// 🪪️ Observes whether the selected child owns its original retirement loan.
pub fn retirement_owner_requires_original_control<O:ErasedSnapshotRetirement>(slot:&Option<O>)->bool{slot.as_ref().is_some_and(|owner|!owner.terminal_is_empty()&&owner.requires_original_control())}
fn admitted<O:ErasedSnapshotRetirement>(slot:&Option<O>,effect:&RetainedAllocationEffect<'_>)->Result<Option<RetirementDemand>,ValueError>{let grant=effect.grant();let d=retirement_owner_demands(slot,grant.maximum_copy_bytes)?;if grant.maximum_items==0{return Ok(None)}if grant.maximum_depth<d.depth{return Err(ValueError::literal(semio_framework_value::ValueRefusalKind::DepthLimit,"inline retirement exceeds admitted depth"))}if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d){return Ok(None)}Ok(Some(d))}
fn done(turn:OriginalRetirementOutcome)->OriginalRetirementPoll{RetainedWorkPoll::Complete(turn)}
fn empty()->OriginalRetirementPoll{done(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}
fn failed(error:ValueError,work:u128)->OriginalRetirementPoll{done(RetainedWorkOutcome{result:Err(error.into()),work})}
fn shell<O>(slot:&mut Option<O>,d:RetirementDemand,effect:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{let work=match semio_framework_value::retirement::record_retirement_work(effect,1){Ok(work)=>work,Err((error,work))=>return failed(error,work)};slot.take();done(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work})}
fn child_result(poll:OriginalRetirementPoll)->OriginalRetirementPoll{match poll{RetainedWorkPoll::Pending{work}=>RetainedWorkPoll::Pending{work},RetainedWorkPoll::Complete(turn)=>done(RetainedWorkOutcome{result:turn.result.map(|step|RetainedCloneStep::Progress(step.progress())),work:turn.work})}}
fn close_with<O:ErasedSnapshotRetirement>(slot:&mut Option<O>,effect:&mut RetainedAllocationEffect<'_>,step:impl FnOnce(RetirementSelection<'_,O>,&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll)->OriginalRetirementPoll{let d=match admitted(slot,effect){Ok(Some(d))=>d,Ok(None)=>return empty(),Err(error)=>return failed(error,0)};let Some(owner)=slot.as_mut()else{return empty()};if owner.terminal_is_empty(){return shell(slot,d,effect)}let selected=match semio_framework_value::select_retirement_cursor(owner,effect.grant().maximum_copy_bytes){Ok(selected)=>selected,Err(error)=>return failed(error,0)};child_result(step(selected,effect))}
/// 🧷️ Closes one original child action or its separately admitted terminal slot.
pub fn retirement_owner_close<O:ErasedSnapshotRetirement>(slot:&mut Option<O>,effect:&mut RetainedAllocationEffect<'_>)->OriginalRetirementPoll{if slot.is_none(){return done(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}close_with(slot,effect,|selected,effect|selected.step(effect))}
/// 🪙️ Closes one inline action through the same original controlled work and physical recipient.
pub fn retirement_owner_close_controlled<O:ErasedSnapshotRetirement>(slot:&mut Option<O>,effect:&mut RetainedAllocationEffect<'_>,control:&mut dyn OriginalRetirementControl)->OriginalRetirementPoll{if slot.is_none(){return done(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}if control.failure_storage_pool().is_empty(){return semio_framework_value::refill_original_failure_storage(control,effect.grant())}close_with(slot,effect,|selected,effect|selected.step_controlled(effect,control))}
/// 🧵️ Closes one inline action through the same original decoder loan.
pub fn retirement_owner_close_original<O:ErasedSnapshotRetirement>(slot:&mut Option<O>,effect:&mut RetainedAllocationEffect<'_>,original:&mut semio_framework_value::OriginalRetirementCloseLoan<'_>)->OriginalRetirementPoll{if slot.is_none(){return done(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}if original.failure_storage_pool().is_empty(){return semio_framework_value::refill_original_failure_storage(original,effect.grant())}close_with(slot,effect,|selected,effect|selected.step_original(effect,original))}

#[cfg(test)]
#[path="🧪️work/effect.rs"]
mod effect;
#[cfg(test)]
mod tests{
 use super::*;use semio_framework_value::RetainedCloneGrant;
 use super::effect::{settled,with_effect};
 struct Leaf(bool);
 impl ErasedSnapshotRetirement for Leaf{
  fn close_step(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>)->OriginalRetirementOutcome{let g=effect.grant();if g.maximum_items==0{return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.0=false;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1}}
  fn terminal_is_empty(&self)->bool{!self.0}fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.0))}
  fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(1)}
 }
 fn close(slot:&mut Option<Leaf>,grant:RetainedCloneGrant)->OriginalRetirementOutcome{settled(with_effect(grant,1,&mut None,|effect|retirement_owner_close(slot,effect)))}
 #[test]fn inline_terminal_shell_is_a_separate_original_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("🧪️work/fixture.json")).unwrap();let mut slot=Some(Leaf(true));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_depth:2,..Default::default()};let child=close(&mut slot,grant);assert_eq!(child.work,law["childWork"].as_u64().unwrap().into());assert!(slot.as_ref().unwrap().terminal_is_empty());assert!(matches!(child.result.unwrap(),RetainedCloneStep::Progress(_)));let demand=retirement_owner_demands(&slot,0).unwrap();assert_eq!(demand,RetirementDemand{copy_bytes:size_of::<Option<Leaf>>(),depth:1,..Default::default()});let denied=close(&mut slot,RetainedCloneGrant{maximum_copy_bytes:0,..grant});assert_eq!(denied.work,law["deniedWork"].as_u64().unwrap().into());assert!(slot.is_some());let shell=close(&mut slot,grant);assert_eq!(shell.work,law["terminalShellWork"].as_u64().unwrap().into());assert!(slot.is_none());}
}
